-- Piano vasca demo più vicino alla realtà: i livelli della scuola nuoto con le fasce da 45 minuti in vasca grande
-- (un corso per corsia), l'ambientamento e l'Acqua Baby nella vasca piccola calda, la vasca grande a 6 corsie e,
-- il mercoledì, a 5. Orari e nomi dei livelli presi dal sito della società (stagione 2026-27); istruttori e persone
-- sono inventati.

-- ── Ripulisco il piano demo precedente (V1003) ──────────────────────────────
delete from evento_spazio;
delete from evento;
delete from lezione_eccezione;
delete from lezione_spazio;
delete from lezione;
delete from corso;

