update spazio set nome = 'Vasca piccola · calda' where id = '00000000-0000-0000-0000-0000000000c2';
update spazio set assetto = 6 where padre_id = '00000000-0000-0000-0000-0000000000c1';
insert into spazio (id, impianto_id, nome, tipo, ordine, padre_id, assetto)
select ('00000000-0000-0000-0000-0000000001' || (10 + n)::text)::uuid, '00000000-0000-0000-0000-0000000000b1',
       'Corsia ' || n, 'CORSIA', 20 + n, '00000000-0000-0000-0000-0000000000c1', 5
from generate_series(1, 5) as n;

