create temporary table piano_demo_id as select gen_random_uuid() as id, d.corso, g as giorno, d.inizio, d.fine, d.spazi
from piano_demo d cross join lateral unnest(d.giorni) as g;

insert into lezione (id, corso_id, giorno_settimana, inizio, fine, valida_dal)
select id, corso, giorno, inizio, fine, date_trunc('year', current_date)::date from piano_demo_id;
insert into lezione_spazio (lezione_id, spazio_id) select id, unnest(spazi) from piano_demo_id;
drop table piano_demo_id;
drop table piano_demo;

